/* assets.js — Asset: immagini incorporate (IMG/IMG3), icone, figure/sprite, medaglioni.
 * Spirit Stones: Remastered — codice originale; immagini fornite dall'autore. */

const IMG={stoneBlue:"data:image/png;base64,",stoneGreen:"data:image/png;base64,",stoneRed:"data:image/png;base64,",stoneGold:"data:image/png;base64,",envForest:"data:image/jpeg;base64,",envLava:"data:image/jpeg;base64,",envTemple:"data:image/jpeg;base64,",envFrozen:"data:image/jpeg;base64,",bossDragon:"data:image/jpeg;base64,",bossShadow:"data:image/jpeg;base64,",bossGolem:"data:image/jpeg;base64,",bossKnight:"data:image/jpeg;base64,",skull:"data:image/png;base64,"};
const IMG3={bgMap:"data:image/jpeg;base64,",bgTeam:"data:image/jpeg;base64,",bgShop:"data:image/jpeg;base64,",bgArena:"data:image/jpeg;base64,",bgMenu:"data:image/jpeg;base64,",hWarrior:"data:image/png;base64,",hMage:"data:image/png;base64,",hArcher:"data:image/png;base64,",hThief:"data:image/png;base64,",eGoblin:"data:image/png;base64,",eSlime:"data:image/png;base64,",eOrc:"data:image/png;base64,",bTreant:"data:image/png;base64,",bDragon:"data:image/png;base64,",navMap:"data:image/png;base64,",navTeam:"data:image/png;base64,",navShop:"data:image/png;base64,",navHome:"data:image/png;base64,",badgeGold:"data:image/png;base64,",badgeGem:"data:image/png;base64,"};
const COIN='<svg class="cur" viewBox="0 0 24 24"><circle cx="12" cy="12" r="9" fill="#ffd85f" stroke="#9c6b16" stroke-width="1.6"/><circle cx="12" cy="12" r="5.6" fill="none" stroke="#c99a2e" stroke-width="1.2"/><path d="M12 8.4l1.2 2.5 2.7.3-2 1.8.6 2.6-2.5-1.3-2.5 1.3.6-2.6-2-1.8 2.7-.3z" fill="#a9741c"/></svg>';
function icSkill(){return '<svg viewBox="0 0 24 24"><path d="M8.5 7 12 3l3.5 4" fill="none" stroke="#c9a24e" stroke-width="1.8" stroke-linecap="round"/><circle cx="12" cy="14" r="6.2" fill="#39d47e" stroke="#0e5c30" stroke-width="1.6"/><circle cx="12" cy="14" r="2.6" fill="#eafff2"/></svg>';}
function icEvo(){return '<svg class="cur" viewBox="0 0 24 24"><path d="M12 2 15 9l7 3-7 3-3 7-3-7-7-3 7-3z" fill="#7ad0ff" stroke="#2a6fb0" stroke-width="1.2"/></svg>';}
function elemIcon(ck){return `<svg viewBox="0 0 24 24">${ICON[ck]}</svg>`;}
function worldMedallion(w,boss){const BG=[IMG.envForest,IMG.envFrozen,IMG.envLava];const bg=BG[w]||IMG.envTemple;return `<span class="medal2${boss?' boss':''}" style="background-image:url(${bg})">${boss?`<img class="medskull" src="${IMG.skull}">`:''}</span>`;}
const ICON={warrior:'<rect x="4.4" y="3.4" width="12" height="5.3" rx="1.3"/><rect x="8.8" y="8.6" width="2.9" height="12" rx="1"/>',thief:'<path d="M12 2c2.3 4 2.3 8.6.8 13.3h-1.7C9.7 10.6 9.7 6 12 2z"/><rect x="7.8" y="15" width="8.4" height="2.3" rx="1"/><rect x="10.9" y="17.3" width="2.2" height="4.2" rx="1"/>',archer:'<path d="M7 2.4a12 12 0 0 1 0 19.2" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"/><path d="M4.5 12h11.8" fill="none" stroke="currentColor" stroke-width="2"/><path d="M12.4 8 18 12l-5.6 4z"/>',mage:'<path d="M13.6 2 5 13.4h4.7L8 22l9.2-11.8h-4.9z"/>',sword:'<rect x="10.6" y="1.8" width="2.9" height="13.6" rx="1"/><rect x="6.8" y="15.4" width="10.4" height="2.4" rx="1"/><rect x="10.9" y="17.8" width="2.2" height="4.3" rx="1"/>',bomb:'<circle cx="11" cy="14.6" r="6.8"/><path d="M15 8.3c2-3 4.3-3 5.3-.8" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round"/>',bow:'<path d="M4 12h12" fill="none" stroke="currentColor" stroke-width="2.2"/><path d="M12 8l5 4-5 4z"/>',potion:'<path d="M10 2.3h4v2h-4z"/><path d="M10.4 4.7h3.2v3l3.1 8.3a4.6 4.6 0 0 1-9.4 0l3.1-8.3z"/>'};
function cvarHex(ck){return (getComputedStyle(document.documentElement).getPropertyValue('--'+ck)||'#888').trim();}
function shade(hex,amt){let h=hex.replace('#','');if(h.length===3)h=h.split('').map(x=>x+x).join('');const n=parseInt(h,16);let r=(n>>16)+amt,g=((n>>8)&255)+amt,b=(n&255)+amt;r=Math.max(0,Math.min(255,r));g=Math.max(0,Math.min(255,g));b=Math.max(0,Math.min(255,b));return '#'+((r<<16)|(g<<8)|b).toString(16).padStart(6,'0');}
function heroFeat(ck,c,dark,ol){
  if(ck==='warrior')return `<path d="M17 8 L15 1.5 L20.5 7Z" fill="${shade(c,50)}" stroke="${ol}" stroke-width="1.2"/><path d="M31 8 L33 1.5 L27.5 7Z" fill="${shade(c,50)}" stroke="${ol}" stroke-width="1.2"/>`;
  if(ck==='thief')return `<path d="M14 12 L9 2 L19 9Z" fill="${c}" stroke="${ol}" stroke-width="1.4"/><path d="M34 12 L39 2 L29 9Z" fill="${c}" stroke="${ol}" stroke-width="1.4"/>`;
  if(ck==='archer')return `<path d="M24 8 Q19 -2 25.5 -.5 Q30 1.5 25.5 8Z" fill="${shade(c,30)}" stroke="${ol}" stroke-width="1.2"/><path d="M24 8 Q23 2 25 0" stroke="${dark}" stroke-width="1" fill="none"/>`;
  return `<path d="M24 -1 l1.7 3.6 4 .4-3 2.7.9 3.9-3.6-2.1-3.6 2.1.9-3.9-3-2.7 4-.4Z" fill="#ffe27a" stroke="${ol}" stroke-width="1"/>`;
}
function heroWeapon(ck,dark,ol){if(ck==='warrior')return `<rect x="36" y="18" width="3" height="18" rx="1" fill="#8a6a3a" stroke="${ol}" stroke-width=".8"/><rect x="33.4" y="14.5" width="8.2" height="6" rx="1.5" fill="#cfd3dd" stroke="${ol}" stroke-width="1"/>`;if(ck==='thief')return `<path d="M37.2 15 L39.6 30 L35.8 30Z" fill="#dde0e8" stroke="${ol}" stroke-width=".9"/><rect x="35.3" y="30" width="4.6" height="2.2" rx=".6" fill="#8a6a3a"/>`;if(ck==='archer')return `<path d="M36 13 a11 11 0 0 1 0 22" fill="none" stroke="#8a6a3a" stroke-width="2"/><path d="M36 24 h-7" stroke="#cfd3dd" stroke-width="1.5"/>`;return `<rect x="36.4" y="13" width="2.6" height="23" rx="1" fill="#8a6a3a" stroke="${ol}" stroke-width=".8"/><circle cx="37.7" cy="12" r="3.2" fill="#7ad0ff" stroke="${ol}" stroke-width="1"/>`;}
function heroFig(ck){const M={warrior:IMG3.hWarrior,thief:IMG3.hThief,archer:IMG3.hArcher,mage:IMG3.hMage};return `<img class="fig sprite" src="${M[ck]}" alt="">`;}
function enemyFig(seed,boss){const P=[IMG3.eGoblin,IMG3.eSlime,IMG3.eOrc];const B=[IMG3.bTreant,IMG3.bDragon];return `<img class="fig sprite" src="${boss?B[((seed%2)+2)%2]:P[((seed%3)+3)%3]}" alt="">`;}
function svgIc(p){return `<svg class="ic" viewBox="0 0 24 24">${p}</svg>`;}
